// Engine-independent collision/navigation helpers, in metres. X/Z is the ground plane.
export const clamp=(v,a,b)=>Math.max(a,Math.min(b,v));
export const distance=(a,b)=>Math.hypot(a.x-b.x,a.z-b.z);
export const seeded=seed=>()=>{seed|=0;seed=seed+0x6d2b79f5|0;let t=Math.imul(seed^seed>>>15,1|seed);t^=t+Math.imul(t^t>>>7,61|t);return((t^t>>>14)>>>0)/4294967296;};
export function segmentDistance(a,b,p){const x=b.x-a.x,y=(b.y||0)-(a.y||0),z=b.z-a.z,n=x*x+y*y+z*z,t=clamp(((p.x-a.x)*x+((p.y||0)-(a.y||0))*y+(p.z-a.z)*z)/(n||1),0,1);return Math.hypot(a.x+x*t-p.x,(a.y||0)+y*t-(p.y||0),a.z+z*t-p.z);}
export function rayBox(a,b,r,pad=0){let lo=0,hi=1;for(const [axis,half]of [['x',r.w/2+pad],['z',r.d/2+pad]]){const delta=b[axis]-a[axis],mn=r[axis]-half,mx=r[axis]+half;if(Math.abs(delta)<1e-8){if(a[axis]<mn||a[axis]>mx)return false;}else{let t=(mn-a[axis])/delta,u=(mx-a[axis])/delta;if(t>u)[t,u]=[u,t];lo=Math.max(lo,t);hi=Math.min(hi,u);if(lo>hi)return false;}}return hi>=0&&lo<=1;}
export const blocked=(a,b,obstacles,pad=.4)=>obstacles.some(r=>rayBox(a,b,r,pad));
export function free(p,obstacles,r=.38,bounds={minX:-11.4,maxX:11.4,minZ:-6.6,maxZ:6.6}){return p.x>=bounds.minX+r&&p.x<=bounds.maxX-r&&p.z>=bounds.minZ+r&&p.z<=bounds.maxZ-r&&!obstacles.some(o=>Math.abs(p.x-o.x)<o.w/2+r&&Math.abs(p.z-o.z)<o.d/2+r);}
export function moveCircle(u,dx,dz,obstacles,bounds){const steps=Math.max(1,Math.ceil(Math.hypot(dx,dz)/.16));for(let i=0;i<steps;i++){if(free({x:u.x+dx/steps,z:u.z},obstacles,u.radius,bounds))u.x+=dx/steps;if(free({x:u.x,z:u.z+dz/steps},obstacles,u.radius,bounds))u.z+=dz/steps;}}
// Breadth-first grid route, with a nearest reachable endpoint; never returns a path through a wall.
export function findPath(a,b,obstacles,r=.4,{minX=-11.4,maxX=11.4,minZ=-6.6,maxZ=6.6,cell=.5}={}){const bounds={minX,maxX,minZ,maxZ};if(free(b,obstacles,r,bounds)&&!blocked(a,b,obstacles,r))return[{x:b.x,z:b.z}];const cols=Math.ceil((maxX-minX)/cell),rows=Math.ceil((maxZ-minZ)/cell),key=(x,z)=>z*cols+x,at=p=>[clamp(Math.floor((p.x-minX)/cell),0,cols-1),clamp(Math.floor((p.z-minZ)/cell),0,rows-1)],point=k=>({x:(k%cols+.5)*cell+minX,z:(Math.floor(k/cols)+.5)*cell+minZ}),[sx,sz]=at(a),[ex,ez]=at(b),start=key(sx,sz),end=key(ex,ez),queue=[start],prev=new Map([[start,-1]]);let best=start,bestD=Infinity;for(let i=0;i<queue.length;i++){const k=queue[i],p=point(k),d=distance(p,b);if(d<bestD){best=k;bestD=d;}if(k===end)break;for(const [dx,dz]of [[-1,0],[1,0],[0,-1],[0,1]]){const x=k%cols+dx,z=Math.floor(k/cols)+dz,n=key(x,z);if(x<0||x>=cols||z<0||z>=rows||prev.has(n)||!free(point(n),obstacles,r,bounds))continue;prev.set(n,k);queue.push(n);}}const path=[];while(best!==start&&best!==-1){path.unshift(point(best));best=prev.get(best);}return path;}
export const turnToward=(angle,target,amount)=>angle+clamp(Math.atan2(Math.sin(target-angle),Math.cos(target-angle)),-amount,amount);
